  "usage.limits": "This is a reference estimate, not an invoice or account balance. Taxes, exchange rates, monthly subscriptions, discounts, server tools, images and audio billing are not calculated. Provider dashboards remain the billing authority.",
  "usage.scope": "Only new calls through Gamja adapters are recorded. Native Core operations can contain retries not separately exposed here; cancelled, failed and interrupted calls may have consumed tokens even when counts are unknown. Direct capability/image probes, other applications and previous usage are not covered. Input/output totals sum only reported counts; the fractions show coverage.",
  "usage.privacy": "The local ledger stores account, connection, model, Agent/room IDs, timestamps and token counts. It stores no prompts, answers or credentials. Price refresh downloads a public catalog without sending your connection or model list.",

