  'report.destination': 'Diagnostic reports go to https://gamja.top/api/gamja-bot/reports when the verified service is available. Submission is unavailable in this build when the receiver has not been configured.',
  'report.contents': 'Reports contain app and build version, operating system and architecture, time, component, stage, fixed error code, occurrence count, and up to 16 fixed transitions. A failure with a sanitized diagnostic also includes a correlation ID, fixed reason and exception class, app-relative stack frames, bounded context IDs, HTTP status, and a validated provider request ID. They contain no chat, agent instructions, provider text, keys, URLs, home paths, process output, clipboard, browser content, screenshots, raw logs, or request and response bodies. An optional manual description is separate and shown before submission.',
